// 6. Sentinel in a circular buffer
public class CircularBuffer {
    private int[] buffer;
    private int head;
    private int tail;
    private boolean sentinelActive;

    public CircularBuffer(int size) {
        buffer = new int[size];
        head = 0;
        tail = 0;
        sentinelActive = true;
        buffer[size - 1] = -1; // Sentinel value
    }

    public void deleteSentinel() {
        if (sentinelActive) {
            buffer[buffer.length - 1] = 0; // Dangerous removal
            sentinelActive = false;
        }
    }
}

