void main (int argc, char **argv) {
char path[256];char *input;int i;short s;unsigned int sz;
i = GetUntrustedInt();s = i;/* s is -1 so it passes the safety check - CWE-697 */if (s > 256) {DiePainfully("go away!\n");}
