import java.util.concurrent.atomic.AtomicInteger;

public class Safe7 {
    static AtomicInteger sharedCounter = new AtomicInteger(Integer.MIN_VALUE);

    public static void main(String[] args) throws InterruptedException {
        Thread t1 = new Thread(() -> {
            sharedCounter.updateAndGet(val -> {
                if (val > Integer.MIN_VALUE) {
                    return val - 1;
                } else {
                    return val; // or handle underflow appropriately
                }
            });
        });
