        Resource res = new Resource();
        pool.push(res);
        // Simulate resource being 'free'
        res.inUse = false;

        // Borrow the resource
        Resource resourceFromPool = pool.pop();
        // Manually 'free' resource
        resourceFromPool.inUse = false;

        // Reuse the resource after 'free'
        resourceFromPool.inUse = true;
        System.out.println("Resource in use: " + resourceFromPool.inUse);

        // Suppose the resource is reused improperly
